def setup(state, run):
    # Refuse collisions before mutating the shared option or existing rows.
    if run in state['rows']:
        raise ValueError('fixture row already exists')
    previous_owner = state.get('_homepage_owner')
    if previous_owner is not None and state['homepage'] != previous_owner['run']:
        previous_owner = None
    receipt = {
        'run': run, 'active': True,
        'previous_homepage': state['homepage'],
        'previous_owner': previous_owner,
    }
    state.setdefault('_row_owners', {})[run] = receipt
    state['_homepage_owner'] = receipt
    state['homepage'] = run
    state['rows'][run] = 'fixture'
    return receipt


def cleanup(state, receipt):
    if not receipt['active']:
        return
    receipt['active'] = False
    run = receipt['run']
    owners = state.get('_row_owners', {})
    if owners.get(run) is receipt:
        if state['rows'].get(run) == 'fixture':
            del state['rows'][run]
        del owners[run]
    if state.get('_homepage_owner') is receipt:
        if state['homepage'] == run:
            previous_homepage = receipt['previous_homepage']
            previous_owner = receipt['previous_owner']
            while previous_owner is not None and not previous_owner['active']:
                previous_homepage = previous_owner['previous_homepage']
                previous_owner = previous_owner['previous_owner']
            state['homepage'] = previous_homepage
            state['_homepage_owner'] = previous_owner
        else:
            state['_homepage_owner'] = None


def first():
    state = {'homepage': 'human-home', 'rows': {'human': 'keep'}}
    run = setup(state, 'one')
    try:
        assert state['rows']['one'] == 'fixture'
    finally:
        cleanup(state, run)
    return state


def second(state):
    run = setup(state, 'two')
    try:
        assert state['rows']['two'] == 'fixture'
    finally:
        cleanup(state, run)
